import{_ as a,o as n,c as e,a2 as p}from"./chunks/framework.EUByU7Iq.js";const u=JSON.parse('{"title":"Redis yum 安装","description":"","frontmatter":{"title":"Redis yum 安装","date":"2020-11-02T00:00:00.000Z","categories":["数据库","Redis"],"tags":["数据库","Redis"]},"headers":[],"relativePath":"blogs/Redis/RedisYUManzhuang.md","filePath":"blogs/Redis/RedisYUM安装.md"}'),i={name:"blogs/Redis/RedisYUManzhuang.md"};function l(r,s,c,d,t,b){return n(),e("div",null,[...s[0]||(s[0]=[p(`<p>Windows 安装很简单，这里不做赘述，下载地址如下：</p><blockquote><p>链接：<a href="https://pan.baidu.com/s/1AX9WtPazap3CVBdu4QcixA" target="_blank" rel="noreferrer">https://pan.baidu.com/s/1AX9WtPazap3CVBdu4QcixA</a></p><p>提取码：<code>5266</code></p></blockquote><h3 id="_1-yum安装-redis" tabindex="-1">1. yum安装 Redis <a class="header-anchor" href="#_1-yum安装-redis" aria-label="Permalink to &quot;1. yum安装 Redis&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>yum install http://rpms.famillecollet.com/enterprise/remi-release-7.rpm -y &amp;&amp; \\</span></span>
<span class="line"><span>yum --enablerepo=remi install redis -y &amp;&amp; \\</span></span>
<span class="line"><span>systemctl enable redis &amp;&amp; \\</span></span>
<span class="line"><span>systemctl start redis &amp;&amp; \\</span></span>
<span class="line"><span>rpm -ql redis</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><img src="https://images2015.cnblogs.com/blog/946553/201702/946553-20170223161957320-1424572697.png" alt=""></p><h3 id="_2-usr-bin-目录下有编译好的redis指令" tabindex="-1">2. <code>/usr/bin</code> 目录下有编译好的redis指令 <a class="header-anchor" href="#_2-usr-bin-目录下有编译好的redis指令" aria-label="Permalink to &quot;2. \`\`\`/usr/bin\`\`\` 目录下有编译好的redis指令&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>redis-benchmark     # 用于进行redis性能测试的工具</span></span>
<span class="line"><span>redis-check-aof     # 用于修复出问题的AOF文件</span></span>
<span class="line"><span>redis-rdb           # 用于修复出问题的rdb文件</span></span>
<span class="line"><span>redis-check-dump    # 用于修复出问题的dump.rdb文件</span></span>
<span class="line"><span>redis-cli           # redis的客户端</span></span>
<span class="line"><span>redis-server        # redis的服务端</span></span>
<span class="line"><span>redis-sentinel      # 用于集群管理</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h3 id="_3-etc-redis-conf" tabindex="-1">3. /etc/redis.conf <a class="header-anchor" href="#_3-etc-redis-conf" aria-label="Permalink to &quot;3. /etc/redis.conf&quot;">​</a></h3><p>redis.conf 现在默认配置挺好的，如非必要，不用定制化修改。下面是简单的修改：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># bind 127.0.0.1 默认不注释，注释后，远程可以访问 redis</span></span>
<span class="line"><span>#bind 127.0.0.1</span></span>
<span class="line"><span></span></span>
<span class="line"><span># requirepass foobared 默认注释，没有密码，后面的foobared为密码</span></span>
<span class="line"><span>requirepass 521666</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 开启 AOF 持久化功能</span></span>
<span class="line"><span>appendonly yes</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h3 id="_4-登录-redis" tabindex="-1">4. 登录 redis <a class="header-anchor" href="#_4-登录-redis" aria-label="Permalink to &quot;4. 登录 redis&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>redis-cli</span></span>
<span class="line"><span># 或</span></span>
<span class="line"><span>redis-cli -h 127.0.0.1 -p 6379</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 输入密码</span></span>
<span class="line"><span>auth 521666</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div>`,12)])])}const m=a(i,[["render",l]]);export{u as __pageData,m as default};
